item.stdout:
My Link Library

A calm place for links worth keeping.

Save
Your library is empty.
Paste a link above to save your first one.<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Link Library — prototype</title>
<style>
  :root {
    --bg: #f7f6f3;
    --card: #ffffff;
    --ink: #2b2b2b;
    --muted: #8a8a83;
    --line: #e7e5df;
    --accent: #5b6cff;
    --accent-soft: #eef0ff;
    --shadow: 0 1px 2px rgba(0,0,0,.04), 0 6px 20px rgba(0,0,0,.04);
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.5;
  }
  .wrap { max-width: 760px; margin: 0 auto; padding: 48px 20px 96px; }
  header h1 { font-size: 22px; font-weight: 650; margin: 0 0 4px; letter-spacing: -.01em; }
  header p { margin: 0 0 28px; color: var(--muted); font-size: 14px; }

  .saver {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 16px;
    box-shadow: var(--shadow);
    display: flex;
    gap: 10px;
    align-items: center;
  }
  .saver input {
    flex: 1;
    border: none;
    outline: none;
    font-size: 15px;
    background: transparent;
    color: var(--ink);
    padding: 8px 6px;
  }
  .saver input::placeholder { color: #b6b4ac; }
  .saver button {
    border: none;
    background: var(--accent);
    color: #fff;
    font-size: 14px;
    font-weight: 600;
    padding: 10px 18px;
    border-radius: 10px;
    cursor: pointer;
    transition: opacity .15s;
    white-space: nowrap;
  }
  .saver button:disabled { opacity: .45; cursor: default; }

  .status { min-height: 20px; margin: 14px 2px 0; font-size: 13px; color: var(--muted); }

  .count { margin: 34px 2px 12px; font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }

  .empty {
    margin-top: 40px;
    text-align: center;
    color: var(--muted);
    font-size: 14px;
    padding: 40px 20px;
  }
  .empty .big { font-size: 15px; color: #6f6d66; margin-bottom: 6px; }

  ul.list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }
  li.item {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 16px 18px;
    box-shadow: var(--shadow);
    animation: rise .25s ease;
  }
  @keyframes rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
  li.item .title { font-size: 16px; font-weight: 600; margin: 0 0 4px; }
  li.item .title a { color: var(--ink); text-decoration: none; }
  li.item .title a:hover { text-decoration: underline; }
  li.item .desc { font-size: 14px; color: #5f5e57; margin: 0 0 10px; }
  li.item .meta { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--muted); }
  li.item .fav { width: 16px; height: 16px; border-radius: 4px; background: var(--accent-soft); color: var(--accent); font-size: 10px; font-weight: 700; display: inline-flex; align-items: center; justify-content: center; }
  li.item.fetching { color: var(--muted); }
  li.item .shimmer { height: 12px; border-radius: 6px; background: linear-gradient(90deg,#eee,#f5f5f5,#eee); background-size: 200% 100%; animation: sh 1.1s infinite; }
  @keyframes sh { from { background-position: 200% 0; } to { background-position: -200% 0; } }
</style>
</head>
<body>
  <div class="wrap">
    <header>
      <h1>My Link Library</h1>
      <p>A calm place for links worth keeping.</p>
    </header>

    <form class="saver" id="saver" autocomplete="off">
      <input id="url" type="text" placeholder="Paste a link and press Save…" aria-label="Link address" />
      <button id="saveBtn" type="submit">Save</button>
    </form>
    <div class="status" id="status"></div>

    <div class="count" id="count" hidden></div>
    <ul class="list" id="list"></ul>
    <div class="empty" id="empty">
      <div class="big">Your library is empty.</div>
      <div>Paste a link above to save your first one.</div>
    </div>
  </div>

<script>
  // ---- Simulated metadata lookup (a prototype stands in for real page fetching) ----
  const KNOWN = {
    "nytimes.com": { site: "The New York Times", title: "How Deep-Sea Cables Quietly Run the Internet", desc: "A look at the fragile undersea network carrying nearly all of the world's data traffic." },
    "wikipedia.org": { site: "Wikipedia", title: "Zettelkasten — the note-taking method", desc: "A system of interconnected notes used by researchers and writers to develop ideas over time." },
    "github.com": { site: "GitHub", title: "sqlite/sqlite: the most-deployed database engine", desc: "Source mirror of SQLite, a small, fast, self-contained SQL database engine." },
    "css-tricks.com": { site: "CSS-Tricks", title: "A Complete Guide to Flexbox", desc: "Everything you need to lay out elements along a row or column, with clear diagrams." },
    "arstechnica.com": { site: "Ars Technica", title: "The quiet revival of the RSS reader", desc: "Why a decades-old technology is finding new life among readers tired of algorithms." }
  };
  function domainOf(raw) {
    try {
      const u = new URL(raw.includes("://") ? raw : "https://" + raw);
      return u.hostname.replace(/^www\./, "");
    } catch (e) { return null; }
  }
  function titleCaseFromUrl(raw) {
    const d = domainOf(raw) || raw;
    const name = d.split(".")[0];
    return name.charAt(0).toUpperCase() + name.slice(1) + " — saved link";
  }
  function lookup(raw) {
    const d = domainOf(raw);
    if (d && KNOWN[d]) return { ...KNOWN[d], domain: d };
    return { site: d || "Web page", title: titleCaseFromUrl(raw), desc: "", domain: d || raw };
  }

  // ---- State ----
  const items = [];
  const listEl = document.getElementById("list");
  const emptyEl = document.getElementById("empty");
  const countEl = document.getElementById("count");
  const statusEl = document.getElementById("status");
  const urlEl = document.getElementById("url");
  const saveBtn = document.getElementById("saveBtn");

  function render() {
    emptyEl.hidden = items.length > 0;
    countEl.hidden = items.length === 0;
    countEl.textContent = items.length + (items.length === 1 ? " link" : " links");
    listEl.innerHTML = "";
    items.forEach(it => {
      const li = document.createElement("li");
      li.className = "item";
      if (it.fetching) {
        li.classList.add("fetching");
        li.innerHTML = `<div class="shimmer" style="width:55%;margin-bottom:8px"></div>
                        <div class="shimmer" style="width:80%;margin-bottom:12px"></div>
                        <div class="meta">Fetching details…</div>`;
      } else {
        const initial = (it.site || "?").charAt(0).toUpperCase();
        li.innerHTML = `
          <div class="title"><a href="${it.url}" target="_blank" rel="noopener">${escapeHtml(it.title)}</a></div>
          ${it.desc ? `<div class="desc">${escapeHtml(it.desc)}</div>` : ""}
          <div class="meta"><span class="fav">${initial}</span><span>${escapeHtml(it.site)}</span><span>·</span><span>${escapeHtml(it.domain)}</span></div>`;
      }
      listEl.appendChild(li);
    });
  }
  function escapeHtml(s){return (s||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}

  document.getElementById("saver").addEventListener("submit", function (e) {
    e.preventDefault();
    const raw = urlEl.value.trim();
    if (!raw) return;
    const item = { url: raw, fetching: true };
    items.unshift(item);
    urlEl.value = "";
    statusEl.textContent = "Saving and looking up the page details…";
    render();
    // Simulate the brief lookup a real app would do in the background.
    setTimeout(() => {
      const meta = lookup(raw);
      Object.assign(item, meta, { fetching: false });
      statusEl.textContent = "Saved. Details filled in for you.";
      render();
      setTimeout(() => { if (statusEl.textContent.startsWith("Saved")) statusEl.textContent = ""; }, 2600);
    }, 850);
  });

  // Ready marker for the review harness.
  document.body.setAttribute("data-harness-ready", "true");
</script>
</body>
</html>

