  const s = document.getElementById("draftSave"), c = document.getElementById("draftCancel");
  if(s) s.onclick = confirmDraft;
  if(c) c.onclick = () => { draft = null; renderDraft(); setStatus(""); };
}
function confirmDraft(){
  const title = document.getElementById("draftTitle").value.trim() || draft.domain;
  const desc = document.getElementById("draftDesc").value.trim();
  const item = { id: Date.now()+"-"+Math.random().toString(36).slice(2,6),
    url:draft.url, domain:draft.domain, site:draft.site, title, desc, image:draft.image, savedAt:draft.savedAt };
  items.unshift(item);
  draft = null; renderDraft();
  setStatus("Saved to your library.", "info"); render(item.id);
  setTimeout(() => { if(statusEl.textContent === "Saved to your library.") setStatus(""); }, 2600);
}

// ---------- Edit later (title, description, AND address) ----------
function startEdit(id, flash){
  const it = items.find(x => x.id === id); if(!it) return;
  it.editing = true;
  it.editAddr = it.url;      // working address
  it.fetchedFor = it.url;    // which address the current details reflect
  it.suggest = null;         // freshly fetched details when address changes
  it.addrErr = "";
  render(flash ? id : null);
  const t = document.getElementById("edit-title-"+id); if(t){ t.focus({preventScroll:true}); }
  const card = document.getElementById("card-"+id); if(card) card.scrollIntoView({behavior:"smooth", block:"center"});
}

function fetchNewAddress(id){
  const it = items.find(x => x.id === id); if(!it) return;
  // Keep the latest typed title/desc so a re-render doesn't lose them.
  stashFields(it);
  const n = normalize(it.editAddr);
  if(!n.ok){ it.addrErr = "That doesn't look like a usable web address."; render(); return; }
  if(n.url !== it.url && items.some(o => o.id !== it.id && o.url === n.url)){
    it.addrErr = "Another saved link already uses that address."; render(); return;
  }
  it.addrErr = "";
  if(n.url === it.url){ it.fetchedFor = it.url; it.suggest = null; render(); return; }
  const meta = lookup(n.domain);
  it.suggest = meta;          // offered, not forced
  it.fetchedFor = n.url;
  // Update the shown source/preview to the new page, but preserve the user's title/desc.
  render();
}

function stashFields(it){
  const t = document.getElementById("edit-title-"+it.id), d = document.getElementById("edit-desc-"+it.id), a = document.getElementById("edit-addr-"+it.id);
  if(t) it.tmpTitle = t.value; if(d) it.tmpDesc = d.value; if(a) it.editAddr = a.value;
}

function saveEdit(id){
